"use client";

import React, { useState, useEffect, useMemo } from "react";
import { Button } from "@/components/ui/button";
import { useClasses } from "@/hooks/useClasses";
import { useCourses } from "@/hooks/useCourses";
import { useTeachers } from "@/hooks/useTeachers";
import { courseService } from "@/lib/api/services/course.service";
import { enrollmentService } from "@/lib/api/services/enrollment.service";
import { toast } from "sonner";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
  SheetFooter,
} from "@/components/ui/sheet";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Badge } from "@/components/ui/badge";
import {
  Plus,
  Pencil,
  Trash2,
  Search,
  Users,
  BookOpen,
  Calendar,
  GraduationCap,
  Eye,
  UserCheck,
} from "lucide-react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

import { AppSidebar } from "@/components/app-sidebar";
import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar";
import NavbarH from "@/components/ui/heroui/navbar";

import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";

interface Curso {
  id: string;
  nome: string;
}

interface Docente {
  id: string;
  nome: string;
  disciplina: string;
}

interface Estudante {
  id: string;
  nome: string;
  numero: string;
  email: string;
}

interface Disciplina {
  id: string;
  nome: string;
  codigo: string;
}

interface Turma {
  id: string;
  nome: string;
  curso: string;
  cursoNome: string;
  semestre: number;
  anoLetivo: string;
  docentes: string[];
  docentesNomes: string[];
  estudantes: string[];
  estado: "Ativa" | "Concluída";
  disciplinas: string[];
  limiteEstudantes?: number; // 👈 ADICIONA ESTA LINHA
}

export default function Academica() {
  const [cursos] = useState<Curso[]>([
    { id: "1", nome: "Engenharia Informática" },
    { id: "2", nome: "Gestão de Empresas" },
    { id: "3", nome: "Direito" },
  ]);

  const [docentes] = useState<Docente[]>([
    { id: "1", nome: "Dr. João Silva", disciplina: "Programação" },
    { id: "2", nome: "Dra. Maria Santos", disciplina: "Base de Dados" },
    { id: "3", nome: "Prof. Carlos Mendes", disciplina: "Matemática" },
    { id: "4", nome: "Profa. Ana Costa", disciplina: "Física" },
  ]);

  const [estudantes] = useState<Estudante[]>([
    {
      id: "1",
      nome: "Pedro Martins",
      numero: "2023001",
      email: "pedro.martins@email.com",
    },
    {
      id: "2",
      nome: "Sofia Rodrigues",
      numero: "2023002",
      email: "sofia.rodrigues@email.com",
    },
    {
      id: "3",
      nome: "Miguel Ferreira",
      numero: "2023003",
      email: "miguel.ferreira@email.com",
    },
    {
      id: "4",
      nome: "Beatriz Alves",
      numero: "2023004",
      email: "beatriz.alves@email.com",
    },
    {
      id: "5",
      nome: "Tiago Oliveira",
      numero: "2023005",
      email: "tiago.oliveira@email.com",
    },
    {
      id: "6",
      nome: "Carolina Sousa",
      numero: "2023006",
      email: "carolina.sousa@email.com",
    },
  ]);

  const estudantesOrdenados = [...estudantes].sort((a, b) =>
    a.nome.localeCompare(b.nome, "pt", { sensitivity: "base" })
  );

  const [disciplinas] = useState<Disciplina[]>([
    { id: "1", nome: "Programação I", codigo: "PROG-101" },
    { id: "2", nome: "Base de Dados", codigo: "BD-201" },
    { id: "3", nome: "Matemática", codigo: "MAT-101" },
    { id: "4", nome: "Física", codigo: "FIS-101" },
  ]);

  const [turmas, setTurmas] = useState<Turma[]>([
    {
      id: "1",
      nome: "1ºAno-A",
      curso: "1",
      cursoNome: "Engenharia Informática",
      semestre: 1,
      anoLetivo: "2024/2025",
      docentes: ["1", "2"],
      docentesNomes: ["Dr. João Silva", "Dra. Maria Santos"],
      estudantes: ["1", "2", "3"],
      estado: "Ativa",
      disciplinas: ["1", "2"],
    },
    {
      id: "2",
      nome: "2ºAno-B",
      curso: "1",
      cursoNome: "Engenharia Informática",
      semestre: 3,
      anoLetivo: "2024/2025",
      docentes: ["3"],
      docentesNomes: ["Prof. Carlos Mendes"],
      estudantes: ["4", "5", "6"],
      estado: "Ativa",
      disciplinas: ["3"],
    },
  ]);

  const [isSheetOpen, setIsSheetOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [turmaToDelete, setTurmaToDelete] = useState<string | null>(null);
  const [detailsDialog, setDetailsDialog] = useState<Turma | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [filterCurso, setFilterCurso] = useState("todos");
  const [filterEstado, setFilterEstado] = useState("todos");

  const [formData, setFormData] = useState<Turma>({
    id: "",
    nome: "",
    curso: "",
    cursoNome: "",
    semestre: 1,
    anoLetivo: "",
    docentes: [],
    docentesNomes: [],
    estudantes: [],
    estado: "Ativa",
    disciplinas: [],
  });

  const handleCreateTurma = () => {
    setIsEditing(false);

    // Ordena alfabeticamente
    const estudantesOrdenados = [...estudantes].sort((a, b) =>
      a.nome.localeCompare(b.nome, "pt", { sensitivity: "base" })
    );

    // Respeita o limite, se existir
    const estudantesAutomaticos = estudantesOrdenados
      .slice(0, formData.limiteEstudantes || estudantesOrdenados.length)
      .map((e) => e.id);

    // Define nova turma
    setFormData({
      id: "",
      nome: "",
      curso: "",
      cursoNome: "",
      semestre: 1,
      anoLetivo:
        new Date().getFullYear() + "/" + (new Date().getFullYear() + 1),
      docentes: [],
      docentesNomes: [],
      estudantes: estudantesAutomaticos, // alunos automáticos
      estado: "Ativa",
      disciplinas: [],
      limiteEstudantes: 30, // valor padrão inicial
    });

    setIsSheetOpen(true);
  };

  const handleEditTurma = (turma: Turma) => {
    setIsEditing(true);
    setFormData(turma);
    setIsSheetOpen(true);
  };

  const handleSaveTurma = () => {
    if (!formData.nome || !formData.curso || !formData.anoLetivo) {
      alert("Por favor, preencha todos os campos obrigatórios");
      return;
    }

    const cursoSelecionado = cursos.find((c) => c.id === formData.curso);
    const docentesSelecionados = docentes
      .filter((d) => formData.docentes.includes(d.id))
      .map((d) => d.nome);

    if (isEditing) {
      setTurmas(
        turmas.map((t) =>
          t.id === formData.id
            ? {
                ...formData,
                cursoNome: cursoSelecionado?.nome || "",
                docentesNomes: docentesSelecionados,
              }
            : t
        )
      );
    } else {
      const novaTurma: Turma = {
        ...formData,
        id: Date.now().toString(),
        cursoNome: cursoSelecionado?.nome || "",
        docentesNomes: docentesSelecionados,
      };
      setTurmas([...turmas, novaTurma]);
    }

    setIsSheetOpen(false);
  };

  const handleDeleteTurma = (id: string) => {
    setTurmas(turmas.filter((t) => t.id !== id));
    setTurmaToDelete(null);
  };

  const toggleDocente = (docenteId: string) => {
    setFormData((prev) => ({
      ...prev,
      docentes: prev.docentes.includes(docenteId)
        ? prev.docentes.filter((id) => id !== docenteId)
        : [...prev.docentes, docenteId],
    }));
  };

  const toggleEstudante = (estudanteId: string) => {
    setFormData((prev) => {
      const jaSelecionado = prev.estudantes.includes(estudanteId);

      // Se for tentar adicionar e já atingiu o limite
      if (
        !jaSelecionado &&
        prev.limiteEstudantes &&
        prev.estudantes.length >= prev.limiteEstudantes
      ) {
        alert(`Limite de ${prev.limiteEstudantes} estudantes atingido.`);
        return prev;
      }

      return {
        ...prev,
        estudantes: jaSelecionado
          ? prev.estudantes.filter((id) => id !== estudanteId)
          : [...prev.estudantes, estudanteId],
      };
    });
  };

  const toggleDisciplina = (disciplinaId: string) => {
    setFormData((prev) => ({
      ...prev,
      disciplinas: prev.disciplinas.includes(disciplinaId)
        ? prev.disciplinas.filter((id) => id !== disciplinaId)
        : [...prev.disciplinas, disciplinaId],
    }));
  };

  const turmasFiltradas = turmas.filter((turma) => {
    const matchSearch =
      turma.nome.toLowerCase().includes(searchTerm.toLowerCase()) ||
      turma.cursoNome.toLowerCase().includes(searchTerm.toLowerCase());
    const matchCurso = filterCurso === "todos" || turma.curso === filterCurso;
    const matchEstado =
      filterEstado === "todos" || turma.estado === filterEstado;

    return matchSearch && matchCurso && matchEstado;
  });

  const totalTurmas = turmas.length;
  const turmasAtivas = turmas.filter((t) => t.estado === "Ativa").length;
  const totalEstudantes = turmas.reduce(
    (acc, t) => acc + t.estudantes.length,
    0
  );

  return (
    <SidebarProvider
      style={
        {
          "--sidebar-width": "calc(var(--spacing) * 72)",
          "--header-height": "calc(var(--spacing) * 12)",
        } as React.CSSProperties
      }
    >
      <AppSidebar variant="sidebar" />

      <SidebarInset>
        {/* <SiteHeader /> */}
        <div className="flex flex-1 flex-col">
          <div className="@container/main flex flex-1 flex-col gap-2">
            <NavbarH />
            <div className="min-h-screen">
              <div className="max-w-7xl mx-auto p-6 space-y-6">
                <div className="flex justify-between items-center">
                  <div>
                    <h1 className="text-3xl font-bold">Gestão de Turmas</h1>
                    <p className="text-gray-500 mt-1">
                      Gerencie turmas, docentes e estudantes
                    </p>
                  </div>
                  <Button onClick={handleCreateTurma} className="gap-2">
                    <Plus className="h-4 w-4" />
                    Nova Turma
                  </Button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                      <CardTitle className="text-sm font-medium">
                        Total de Turmas
                      </CardTitle>
                      <GraduationCap className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                      <div className="text-2xl font-bold">{totalTurmas}</div>
                    </CardContent>
                  </Card>
                  <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                      <CardTitle className="text-sm font-medium">
                        Turmas Ativas
                      </CardTitle>
                      <UserCheck className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                      <div className="text-2xl font-bold">{turmasAtivas}</div>
                    </CardContent>
                  </Card>
                  <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                      <CardTitle className="text-sm font-medium">
                        Total de Estudantes
                      </CardTitle>
                      <Users className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                      <div className="text-2xl font-bold">
                        {totalEstudantes}
                      </div>
                    </CardContent>
                  </Card>
                </div>

                <Card>
                  <CardContent className="pt-6">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                      <div className="relative">
                        <Search className="absolute left-3 top-3 h-4 w-4 text-gray-400" />
                        <Input
                          placeholder="Pesquisar turmas..."
                          value={searchTerm}
                          onChange={(e) => setSearchTerm(e.target.value)}
                          className="pl-10"
                        />
                      </div>
                      <Select
                        value={filterCurso}
                        onValueChange={setFilterCurso}
                      >
                        <SelectTrigger>
                          <SelectValue placeholder="Filtrar por curso" />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="todos">Todos os Cursos</SelectItem>
                          {cursos.map((curso) => (
                            <SelectItem key={curso.id} value={curso.id}>
                              {curso.nome}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                      <Select
                        value={filterEstado}
                        onValueChange={setFilterEstado}
                      >
                        <SelectTrigger>
                          <SelectValue placeholder="Filtrar por estado" />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="todos">
                            Todos os Estados
                          </SelectItem>
                          <SelectItem value="Ativa">Ativa</SelectItem>
                          <SelectItem value="Concluída">Concluída</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>
                  </CardContent>
                </Card>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {turmasFiltradas.map((turma) => (
                    <Card
                      key={turma.id}
                      className="hover:shadow-lg transition-shadow"
                    >
                      <CardHeader>
                        <div className="flex justify-between items-start">
                          <div className="flex-1">
                            <CardTitle className="text-lg">
                              {turma.nome}
                            </CardTitle>
                            <CardDescription className="mt-1">
                              {turma.cursoNome}
                            </CardDescription>
                          </div>
                          <Badge
                            variant={
                              turma.estado === "Ativa" ? "default" : "secondary"
                            }
                          >
                            {turma.estado}
                          </Badge>
                        </div>
                      </CardHeader>
                      <CardContent>
                        <div className="space-y-3">
                          <div className="flex items-center gap-2 text-sm">
                            <Calendar className="h-4 w-4 text-gray-500" />
                            <span className="text-gray-600">Ano Letivo:</span>
                            <span className="font-medium">
                              {turma.anoLetivo}
                            </span>
                          </div>
                          <div className="flex items-center gap-2 text-sm">
                            <BookOpen className="h-4 w-4 text-gray-500" />
                            <span className="text-gray-600">Semestre:</span>
                            <span className="font-medium">
                              {turma.semestre}º
                            </span>
                          </div>
                          <div className="flex items-center gap-2 text-sm">
                            <Users className="h-4 w-4 text-gray-500" />
                            <span className="text-gray-600">Estudantes:</span>
                            <span className="font-medium">
                              {turma.estudantes.length}
                            </span>
                          </div>
                          <div className="text-sm">
                            <span className="text-gray-600">Docentes:</span>
                            <div className="mt-1 space-y-1">
                              {turma.docentesNomes
                                .slice(0, 2)
                                .map((nome, idx) => (
                                  <div
                                    key={idx}
                                    className="text-xs bg-transparent px-2 py-1 rounded"
                                  >
                                    {nome}
                                  </div>
                                ))}
                              {turma.docentesNomes.length > 2 && (
                                <div className="text-xs text-gray-500">
                                  +{turma.docentesNomes.length - 2} mais
                                </div>
                              )}
                            </div>
                          </div>
                        </div>
                        <div className="flex gap-2 mt-4 pt-4 border-t">
                          <Button
                            variant="outline"
                            size="sm"
                            className="flex-1"
                            onClick={() => setDetailsDialog(turma)}
                          >
                            <Eye className="h-4 w-4 mr-2" />
                            Detalhes
                          </Button>
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleEditTurma(turma)}
                          >
                            <Pencil className="h-4 w-4" />
                          </Button>
                          <Button
                            variant="destructive"
                            size="sm"
                            onClick={() => setTurmaToDelete(turma.id)}
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>

                {turmasFiltradas.length === 0 && (
                  <Card>
                    <CardContent className="py-12 text-center">
                      <p className="text-gray-500">Nenhuma turma encontrada</p>
                    </CardContent>
                  </Card>
                )}
              </div>

              <Sheet open={isSheetOpen} onOpenChange={setIsSheetOpen}>
                <SheetContent className="sm:max-w-2xl overflow-y-auto">
                  <SheetHeader>
                    <SheetTitle>
                      {isEditing ? "Editar Turma" : "Nova Turma"}
                    </SheetTitle>
                    <SheetDescription>
                      Preencha os dados da turma abaixo
                    </SheetDescription>
                  </SheetHeader>

                  <div className="space-y-4 py-4 pl-7 pr-5">
                    {/* 🧭 Dados principais da turma */}
                    <div className="space-y-4">
                      {/* Nome da Turma */}
                      <div className="space-y-2">
                        <Label htmlFor="nome">Nome da Turma *</Label>
                        <Input
                          id="nome"
                          value={formData.nome}
                          onChange={(e) =>
                            setFormData({ ...formData, nome: e.target.value })
                          }
                          placeholder="Ex: 1º Ano - A"
                        />
                      </div>

                      {/* Curso, Semestre e Estado na mesma linha */}
                      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        {/* Curso */}
                        <div className="space-y-2">
                          <Label htmlFor="curso">Curso *</Label>
                          <Select
                            value={formData.curso}
                            onValueChange={(value) =>
                              setFormData({ ...formData, curso: value })
                            }
                          >
                            <SelectTrigger id="curso">
                              <SelectValue placeholder="Selecione o curso" />
                            </SelectTrigger>
                            <SelectContent>
                              {cursos.map((curso) => (
                                <SelectItem key={curso.id} value={curso.id}>
                                  {curso.nome}
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        </div>

                        {/* Semestre */}
                        <div className="space-y-2">
                          <Label htmlFor="semestre">Semestre *</Label>
                          <Select
                            value={formData.semestre.toString()}
                            onValueChange={(value) =>
                              setFormData({
                                ...formData,
                                semestre: parseInt(value),
                              })
                            }
                          >
                            <SelectTrigger id="semestre">
                              <SelectValue placeholder="Selecione" />
                            </SelectTrigger>
                            <SelectContent>
                              {[1, 2, 3, 4, 5, 6, 7, 8].map((sem) => (
                                <SelectItem key={sem} value={sem.toString()}>
                                  {sem}º
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        </div>

                        {/* Estado */}
                        <div className="space-y-2">
                          <Label htmlFor="estado">Estado</Label>
                          <Select
                            value={formData.estado}
                            onValueChange={(value: "Ativa" | "Concluída") =>
                              setFormData({ ...formData, estado: value })
                            }
                          >
                            <SelectTrigger id="estado">
                              <SelectValue placeholder="Selecione" />
                            </SelectTrigger>
                            <SelectContent>
                              <SelectItem value="Ativa">Ativa</SelectItem>
                              <SelectItem value="Concluída">
                                Concluída
                              </SelectItem>
                            </SelectContent>
                          </Select>
                        </div>
                      </div>

                      {/* Ano Letivo */}
                      <div className="space-y-2">
                        <Label htmlFor="anoLetivo">Ano Letivo *</Label>
                        <Input
                          id="anoLetivo"
                          value={formData.anoLetivo}
                          onChange={(e) =>
                            setFormData({
                              ...formData,
                              anoLetivo: e.target.value,
                            })
                          }
                          placeholder="Ex: 2024/2025"
                        />
                      </div>
                    </div>

                    <div className="space-y-2">
                      <Label htmlFor="limiteEstudantes">
                        Número máximo de estudantes
                      </Label>
                      <Input
                        id="limiteEstudantes"
                        type="number"
                        min={1}
                        value={formData.limiteEstudantes || ""}
                        onChange={(e) =>
                          setFormData({
                            ...formData,
                            limiteEstudantes: parseInt(e.target.value) || 0,
                          })
                        }
                        placeholder="Ex: 30"
                      />
                    </div>

                    <div className="space-y-2">
                      <Label>Disciplinas</Label>
                      <Card>
                        <CardContent className="pt-4 max-h-40 overflow-y-auto">
                          <div className="space-y-2">
                            {disciplinas.map((disciplina) => (
                              <label
                                key={disciplina.id}
                                className="flex items-center gap-2 p-2 hover:bg-gray-50 hover:text-[#09090b] rounded cursor-pointer"
                              >
                                <input
                                  type="checkbox"
                                  checked={formData.disciplinas.includes(
                                    disciplina.id
                                  )}
                                  onChange={() =>
                                    toggleDisciplina(disciplina.id)
                                  }
                                  className="rounded"
                                />
                                <div className="flex-1">
                                  <div className="font-medium text-sm">
                                    {disciplina.nome}
                                  </div>
                                  <div className="text-xs text-gray-500">
                                    {disciplina.codigo}
                                  </div>
                                </div>
                              </label>
                            ))}
                          </div>
                        </CardContent>
                      </Card>
                    </div>

                    <div className="space-y-2">
                      <Label>Docentes Atribuídos</Label>
                      <Card>
                        <CardContent className="pt-4 max-h-48 overflow-y-auto">
                          <div className="space-y-2">
                            {docentes.map((docente) => (
                              <label
                                key={docente.id}
                                className="flex items-center gap-2 p-2 hover:bg-gray-50 hover:text-[#09090b] rounded cursor-pointer"
                              >
                                <input
                                  type="checkbox"
                                  checked={formData.docentes.includes(
                                    docente.id
                                  )}
                                  onChange={() => toggleDocente(docente.id)}
                                  className="rounded"
                                />
                                <div className="flex-1">
                                  <div className="font-medium text-sm">
                                    {docente.nome}
                                  </div>
                                  <div className="text-xs text-gray-500">
                                    {docente.disciplina}
                                  </div>
                                </div>
                              </label>
                            ))}
                          </div>
                        </CardContent>
                      </Card>
                    </div>

                    <div className="space-y-2">
                      <Label>
                        Estudantes ({formData.estudantes.length} selecionados)
                      </Label>
                      <Card>
                        <CardContent className="pt-4 max-h-64 overflow-y-auto">
                          <div className="space-y-2">
                            {estudantesOrdenados.map((estudante) => (
                              <TooltipProvider key={estudante.id}>
                                <Tooltip>
                                  <TooltipTrigger asChild>
                                    <label className="flex items-center gap-2 p-2 hover:bg-gray-50 hover:text-[#09090b] rounded cursor-pointer">
                                      <input
                                        type="checkbox"
                                        checked={formData.estudantes.includes(
                                          estudante.id
                                        )}
                                        onChange={() =>
                                          toggleEstudante(estudante.id)
                                        }
                                        className="rounded"
                                      />
                                      <div className="flex-1 font-medium text-sm">
                                        {estudante.nome}
                                      </div>
                                    </label>
                                  </TooltipTrigger>

                                  <TooltipContent>
                                    <div className="text-xs">
                                      <p>
                                        <strong>Número:</strong>{" "}
                                        {estudante.numero}
                                      </p>
                                      <p>
                                        <strong>Email:</strong>{" "}
                                        {estudante.email}
                                      </p>
                                    </div>
                                  </TooltipContent>
                                </Tooltip>
                              </TooltipProvider>
                            ))}
                          </div>
                        </CardContent>
                      </Card>
                    </div>
                  </div>

                  <SheetFooter>
                    <Button
                      variant="outline"
                      onClick={() => setIsSheetOpen(false)}
                    >
                      Cancelar
                    </Button>
                    <Button onClick={handleSaveTurma}>
                      {isEditing ? "Salvar Alterações" : "Criar Turma"}
                    </Button>
                  </SheetFooter>
                </SheetContent>
              </Sheet>

              <Dialog
                open={!!detailsDialog}
                onOpenChange={() => setDetailsDialog(null)}
              >
                <DialogContent className="max-w-4xl max-h-[80vh] overflow-y-auto">
                  <DialogHeader>
                    <DialogTitle className="text-2xl">
                      Detalhes da Turma: {detailsDialog?.nome}
                    </DialogTitle>
                    <DialogDescription>
                      {detailsDialog?.cursoNome} • {detailsDialog?.anoLetivo}
                    </DialogDescription>
                  </DialogHeader>

                  {detailsDialog && (
                    <div className="space-y-6 py-4">
                      <Card>
                        <CardHeader>
                          <CardTitle className="text-lg">
                            Informações Gerais
                          </CardTitle>
                        </CardHeader>
                        <CardContent className="grid grid-cols-2 gap-4">
                          <div>
                            <Label className="text-gray-500">Semestre</Label>
                            <p className="font-medium">
                              {detailsDialog.semestre}º
                            </p>
                          </div>
                          <div>
                            <Label className="text-gray-500">Estado</Label>
                            <Badge
                              className="mt-1"
                              variant={
                                detailsDialog.estado === "Ativa"
                                  ? "default"
                                  : "secondary"
                              }
                            >
                              {detailsDialog.estado}
                            </Badge>
                          </div>
                          <div>
                            <Label className="text-gray-500">
                              Nº de Estudantes
                            </Label>
                            <p className="font-medium">
                              {detailsDialog.estudantes.length}
                            </p>
                          </div>
                          <div>
                            <Label className="text-gray-500">
                              Nº de Docentes
                            </Label>
                            <p className="font-medium">
                              {detailsDialog.docentes.length}
                            </p>
                          </div>
                        </CardContent>
                      </Card>

                      <Card>
                        <CardHeader>
                          <CardTitle className="text-lg">Disciplinas</CardTitle>
                        </CardHeader>
                        <CardContent>
                          <div className="flex flex-wrap gap-2">
                            {detailsDialog.disciplinas.length > 0 ? (
                              detailsDialog.disciplinas.map((discId) => {
                                const disc = disciplinas.find(
                                  (d) => d.id === discId
                                );
                                return disc ? (
                                  <Badge key={discId} variant="outline">
                                    {disc.nome}
                                  </Badge>
                                ) : null;
                              })
                            ) : (
                              <p className="text-gray-500 text-sm">
                                Nenhuma disciplina atribuída
                              </p>
                            )}
                          </div>
                        </CardContent>
                      </Card>

                      <Card>
                        <CardHeader>
                          <CardTitle className="text-lg">
                            Docentes Atribuídos
                          </CardTitle>
                        </CardHeader>
                        <CardContent>
                          <div className="space-y-2">
                            {detailsDialog.docentesNomes.length > 0 ? (
                              detailsDialog.docentesNomes.map((nome, idx) => (
                                <div
                                  key={idx}
                                  className="flex items-center gap-2 p-2 bg-transparent rounded"
                                >
                                  <Users className="h-4 w-4 text-gray-500" />
                                  <span>{nome}</span>
                                </div>
                              ))
                            ) : (
                              <p className="text-gray-500 text-sm">
                                Nenhum docente atribuído
                              </p>
                            )}
                          </div>
                        </CardContent>
                      </Card>

                      <Card>
                        <CardHeader>
                          <CardTitle className="text-lg">
                            Lista de Estudantes
                          </CardTitle>
                        </CardHeader>
                        <CardContent>
                          {detailsDialog.estudantes.length > 0 ? (
                            <Table>
                              <TableHeader>
                                <TableRow>
                                  <TableHead>Número</TableHead>
                                  <TableHead>Nome</TableHead>
                                  <TableHead>Email</TableHead>
                                </TableRow>
                              </TableHeader>
                              <TableBody>
                                {detailsDialog.estudantes.map((estudanteId) => {
                                  const estudante = estudantes.find(
                                    (e) => e.id === estudanteId
                                  );
                                  return estudante ? (
                                    <TableRow key={estudante.id}>
                                      <TableCell>{estudante.numero}</TableCell>
                                      <TableCell>{estudante.nome}</TableCell>
                                      <TableCell>{estudante.email}</TableCell>
                                    </TableRow>
                                  ) : null;
                                })}
                              </TableBody>
                            </Table>
                          ) : (
                            <p className="text-gray-500 text-sm">
                              Nenhum estudante matriculado
                            </p>
                          )}
                        </CardContent>
                      </Card>
                    </div>
                  )}
                </DialogContent>
              </Dialog>

              <AlertDialog
                open={!!turmaToDelete}
                onOpenChange={() => setTurmaToDelete(null)}
              >
                <AlertDialogContent>
                  <AlertDialogHeader>
                    <AlertDialogTitle>Confirmar Exclusão</AlertDialogTitle>
                    <AlertDialogDescription>
                      Tem certeza que deseja excluir esta turma? Esta ação não
                      pode ser desfeita.
                    </AlertDialogDescription>
                  </AlertDialogHeader>
                  <AlertDialogFooter>
                    <AlertDialogCancel>Cancelar</AlertDialogCancel>
                    <AlertDialogAction
                      onClick={() =>
                        turmaToDelete && handleDeleteTurma(turmaToDelete)
                      }
                      className="bg-red-600 hover:bg-red-700"
                    >
                      Excluir
                    </AlertDialogAction>
                  </AlertDialogFooter>
                </AlertDialogContent>
              </AlertDialog>
            </div>
          </div>
        </div>
      </SidebarInset>
    </SidebarProvider>
  );
}
